const input = $input.first().json;
const replay = input.result?.canonical_result;
const live = input.structuredContent?.response;
const canonical = replay ?? live;
if (!canonical || canonical.schema_version !== 'travel.hotel_search.v1') throw new Error('Missing canonical hotel result');
if (input.result?.expired) throw new Error('Protected hotel result has expired');
const resultRef = input.result?.result_ref ?? canonical.result_ref;
const offers = canonical.offers.slice(0, 5);
if (!resultRef || offers.length === 0) throw new Error('Hotel result is incomplete');
const ranked = [...offers].sort((a, b) => Number(b.refundable) - Number(a.refundable) || (b.star_rating ?? 0) - (a.star_rating ?? 0) || (a.distance_km ?? 999) - (b.distance_km ?? 999) || a.total_amount - b.total_amount);
const options = offers.map((offer) => ({ key: offer.offer_key, label: offer.name, summary: `${offer.star_rating ?? 'Unrated'}-star property, ${offer.distance_km ?? 'unknown'} km away, totaling ${offer.total_currency} ${offer.total_amount}.`, attributes: { total_amount: offer.total_amount, currency: offer.total_currency, refundable: offer.refundable, free_cancellation: offer.free_cancellation, breakfast_included: offer.breakfast_included, payment_timing: offer.payment_timing, distance_km: offer.distance_km, star_rating: offer.star_rating } }));
const sourceUrl = canonical.provider === 'duffel' ? 'https://duffel.com/' : 'https://www.routestack.ai/';
return [{ json: { schema_version: 'research.v1', summary: `${canonical.provider} returned ${canonical.offer_count} hotel offers; ${canonical.returned_count} were normalized.`, options, recommendation: { option_key: ranked[0].offer_key, rationale: 'Deterministic ranking favors refundability, rating, proximity, then price.' }, sources: [{ key: `${canonical.provider}-live-inventory`, title: `${canonical.provider} live hotel inventory`, url: sourceUrl }], constraints: { result_ref: resultRef, valid_until: canonical.valid_until }, caveats: ['Inventory and prices require revalidation after the protected result expires.'] } }];
